#!/bin/sh
# PyTools target-machine acceptance smoke test (Kylin V10 / UOS V20 x86_64).
# Self-contained: embeds synthetic fixtures, needs no Python/network/Office.
# Usage:
#   sh verify_target.sh                     # auto-locates pytools
#   PYTOOLS_BIN=/path/to/pytools sh verify_target.sh
# Results print per-test PASS/FAIL plus a summary, and are kept in the
# work directory printed at the end. Exit code 0 iff every test passes.
# NOTE: passing here is a provisional pass; final acceptance still needs
# the real target machine and real business workbooks.
set -u

PYTOOLS="${PYTOOLS_BIN:-}"
if [ -z "$PYTOOLS" ]; then
    for candidate in "./pytools" "$(dirname "$0")/pytools" "/usr/bin/pytools"; do
        if [ -x "$candidate" ]; then PYTOOLS="$candidate"; break; fi
    done
fi
if [ -z "$PYTOOLS" ] || [ ! -x "$PYTOOLS" ]; then
    echo "FAIL: pytools executable not found (set PYTOOLS_BIN=/path/to/pytools)"
    exit 2
fi

PASS=0; FAIL=0; FAILED=""
WORK="$(mktemp -d /tmp/pytools-verify.XXXXXX)"

emit() { # emit <relative-path> <base64>
    mkdir -p "$WORK/$(dirname "$1")"
    printf '%s' "$2" | base64 -d > "$WORK/$1"
}

report() { # report <name> <ok:0|1> <detail-file>
    if [ "$2" = "0" ]; then
        PASS=$((PASS+1)); echo "PASS  $1"
    else
        FAIL=$((FAIL+1)); FAILED="$FAILED $1"; echo "FAIL  $1"
        echo "      ---- output tail ----"
        tail -n 6 "$3" 2>/dev/null | sed 's/^/      /'
    fi
}

echo "== PyTools target smoke =="
echo "binary : $PYTOOLS"
echo "host   : $(uname -m) $(uname -r)"
echo "glibc  : $(ldd --version 2>/dev/null | head -1)"
MISSING_LIBS="$(ldd "$PYTOOLS" 2>&1 | grep 'not found' || true)"
echo "ldd    : $(ldd "$PYTOOLS" 2>/dev/null | wc -l) libs"
if [ -n "$MISSING_LIBS" ]; then
    echo "FAIL   ldd reports missing libraries:"
    echo "$MISSING_LIBS" | sed 's/^/       /'
    exit 2
fi
echo "workdir: $WORK"
echo ""

emit app/config/config.xlsx 
emit app/input/sample_source.xlsx 
emit summary/error_token_matrix.xlsx 
emit comments/comment_template.xlsx 
emit comments/merged_children_source.xlsx 
emit dedup/dedup_ledger.xlsx 

# T1 configuration read
OUT="$WORK/t1.out"; "$PYTOOLS" config-view --config "$WORK/app/config/config.xlsx" >"$OUT" 2>&1
[ $? -eq 0 ] && grep -q "全局配置\|输入目录" "$OUT"; report "T1 config-view" $? "$OUT"

# T2 summary-used-range with Excel error values
OUT="$WORK/t2.out"; "$PYTOOLS" summary-used-range --output-dir "$WORK/o2" \
    --log-dir "$WORK/o2/logs" --log-view user \
    "$WORK/summary/error_token_matrix.xlsx" >"$OUT" 2>&1
RC=$?
SUMMARY_XLSX="$(ls "$WORK/o2"/*.xlsx 2>/dev/null | head -1)"
RUNLOG="$(ls "$WORK/o2/logs"/PT-6-1_*.json 2>/dev/null | head -1)"
if [ $RC -eq 0 ] && [ -n "$SUMMARY_XLSX" ] && [ -s "$SUMMARY_XLSX" ] \
   && [ -n "$RUNLOG" ] && grep -q '"succeeded"' "$RUNLOG"; then OK=0; else OK=1; fi
report "T2 summary-used-range (error values + run history)" $OK "$OUT"

# T3 summary-comments with a comment template
OUT="$WORK/t3.out"; "$PYTOOLS" summary-comments --template \
    "$WORK/comments/comment_template.xlsx" --output-dir "$WORK/o3" \
    "$WORK/comments/merged_children_source.xlsx" >"$OUT" 2>&1
RC=$?
COMMENT_XLSX="$(ls "$WORK/o3"/*.xlsx 2>/dev/null | head -1)"
[ $RC -eq 0 ] && [ -n "$COMMENT_XLSX" ] && [ -s "$COMMENT_XLSX" ]; \
    report "T3 summary-comments" $? "$OUT"

# T4 wide-summary through the config-driven rules
OUT="$WORK/t4.out"; "$PYTOOLS" wide-summary --config "$WORK/app/config/config.xlsx" \
    --log-view developer "$WORK/app/input/sample_source.xlsx" >"$OUT" 2>&1
RC=$?
WIDE_XLSX="$(ls "$WORK/app/output"/*.xlsx 2>/dev/null | head -1)"
if [ $RC -eq 0 ] && grep -q '"output":"' "$OUT" && [ -n "$WIDE_XLSX" ] && [ -s "$WIDE_XLSX" ]; then OK=0; else OK=1; fi
report "T4 wide-summary (rule hit + output)" $OK "$OUT"

# T5 interactive menu starts and exits cleanly
OUT="$WORK/t5.out"; printf '0\n' | "$PYTOOLS" menu --config "$WORK/app/config/config.xlsx" >"$OUT" 2>&1
report "T5 interactive menu smoke" $? "$OUT"

# T6 comment-based duplicate plan (plan file persistence, no capability needed)
OUT="$WORK/t6.out"; "$PYTOOLS" dedup-comment-plan     --input "$WORK/dedup/dedup_ledger.xlsx"     --output "$WORK/o6/candidate.xlsx" --action mark     --plan-output "$WORK/o6/plan.json" >"$OUT" 2>&1
RC=$?
if [ $RC -eq 0 ] && grep -q '"duplicate_rows": 2' "$OUT" && [ -s "$WORK/o6/plan.json" ]; then OK=0; else OK=1; fi
report "T6 dedup plan (plan file + duplicate count)" $OK "$OUT"

# T7 config initialization
OUT="$WORK/t7.out"; "$PYTOOLS" config-init --path "$WORK/o7/config.xlsx" >"$OUT" 2>&1
RC=$?
[ $RC -eq 0 ] && [ -s "$WORK/o7/config.xlsx" ]; report "T7 config-init" $? "$OUT"

# T8 archive date preview
mkdir -p "$WORK/archive_input"
echo "fixture" > "$WORK/archive_input/20260609_存款表.xlsx"
OUT="$WORK/t8.out"; "$PYTOOLS" archive-date-preview     "$WORK/archive_input/20260609_存款表.xlsx"     --target-root "$WORK/archive_target" --output-dir "$WORK/o8" >"$OUT" 2>&1
RC=$?
ARCHIVE_XLSX="$(ls "$WORK/o8"/*.xlsx 2>/dev/null | head -1)"
[ $RC -eq 0 ] && [ -n "$ARCHIVE_XLSX" ] && [ -s "$ARCHIVE_XLSX" ];     report "T8 archive date preview" $? "$OUT"

echo ""
echo "== summary: $PASS passed, $FAIL failed =="
if [ "$FAIL" -gt 0 ]; then echo "failed:$FAILED"; RESULT="PROVISIONAL_FAIL"; else RESULT="PROVISIONAL_PASS"; fi
{
  echo "pytools target smoke $(date '+%F %T')"
  echo "binary: $PYTOOLS"
  echo "host: $(uname -a)"
  echo "glibc: $(ldd --version 2>/dev/null | head -1)"
  echo "result: $RESULT  (passed=$PASS failed=$FAIL)"
} > "$WORK/RESULT.txt"
echo "result file: $WORK/RESULT.txt (workdir kept for inspection)"
[ "$FAIL" -eq 0 ]
